var sb = new System.Text.StringBuilder();
// Check Aeron
var aeron = UnityEngine.GameObject.Find("Aeron_Instance");
var guard = UnityEngine.GameObject.Find("Guard_Instance");
var cam = UnityEngine.Camera.main;
