}
if (guard != null)
{
    var anim = guard.GetComponent<UnityEngine.Animator>();
    sb.AppendLine($"Guard Animator: isInitialized={anim?.isInitialized}, currentClip={anim?.GetCurrentAnimatorClipInfo(0)[0].clip.name}");
}
